#[allow(non_camel_case_types, reason = "schema names are preserved")]
#[allow(non_snake_case, reason = "schema field names are preserved")]
#[derive(Debug, Clone, PartialEq)]
pub struct File {
    pub size_prefix: u32,
    pub magic: u32,
    pub context_data: [u8; 1080],
    pub campaign_index: u32,
    pub main_save_block: [u8; 340],
    pub unit_count: u32,
    pub units: ::std::vec::Vec<UnitSaveData>,
    pub selected_unit_ref: u32,
    pub roster_count: u32,
    pub roster_entries: ::std::vec::Vec<WorldMapNodeState>,
    pub second_array_count: u32,
    pub second_array: ::std::vec::Vec<u32>,
    pub mission_completion: [u32; 20],
    pub current_mission_slot: u32,
    pub tail_data: ::std::vec::Vec<u8>,
}

impl File {
    #[allow(non_snake_case, reason = "schema field names are preserved")]
    #[allow(clippy::too_many_lines, reason = "schema methods follow field order")]
    pub fn parse(buf: &[u8], offset: &mut usize) -> ::std::result::Result<Self, Error> {
        let size_prefix = u32::from_le_bytes(self::read_array::<4>(buf, offset)?);
        let magic = u32::from_le_bytes(self::read_array::<4>(buf, offset)?);
        #[allow(
            clippy::absurd_extreme_comparisons,
            clippy::float_cmp,
            clippy::manual_range_contains,
            clippy::nonminimal_bool,
            unused_comparisons,
            reason = "validation expressions preserve schema comparisons"
        )]
        if !(magic == 110) {
            return Err(Error::Validation {
                id: "magic.check",
                message: "save magic must be 0x6E",
                field: "magic",
            });
        }
        let context_data = {
            let bytes = self::take(buf, offset, 1080)?;
            <[u8; 1080]>::try_from(bytes).map_err(|_| Error::FixedSize {
                field: "context_data",
                expected: 1080,
                actual: bytes.len(),
            })?
        };
        let campaign_index = u32::from_le_bytes(self::read_array::<4>(buf, offset)?);
        #[allow(
            clippy::absurd_extreme_comparisons,
            clippy::float_cmp,
            clippy::manual_range_contains,
            clippy::nonminimal_bool,
            unused_comparisons,
            reason = "validation expressions preserve schema comparisons"
        )]
        if !(campaign_index <= 3) {
            return Err(Error::Validation {
                id: "campaign_index.max",
                message: "campaign index must be at most 3",
                field: "campaign_index",
            });
        }
        let main_save_block = {
            let bytes = self::take(buf, offset, 340)?;
            <[u8; 340]>::try_from(bytes).map_err(|_| Error::FixedSize {
                field: "main_save_block",
                expected: 340,
                actual: bytes.len(),
            })?
        };
        let unit_count = u32::from_le_bytes(self::read_array::<4>(buf, offset)?);
        let units = {
            let raw_count = unit_count;
            #[allow(
                clippy::unnecessary_fallible_conversions,
                reason = "length fields can use signed or wide integer types"
            )]
            let count = usize::try_from(raw_count).map_err(|_| Error::InvalidLength {
                field: "units",
                value: i128::from(raw_count),
            })?;
            let mut values = ::std::vec::Vec::with_capacity(count);
            for _ in 0..count {
                values.push(UnitSaveData::parse(buf, offset)?);
            }
            values
        };
        let selected_unit_ref = u32::from_le_bytes(self::read_array::<4>(buf, offset)?);
        let roster_count = u32::from_le_bytes(self::read_array::<4>(buf, offset)?);
        let roster_entries = {
            let raw_count = roster_count;
            #[allow(
                clippy::unnecessary_fallible_conversions,
                reason = "length fields can use signed or wide integer types"
            )]
            let count = usize::try_from(raw_count).map_err(|_| Error::InvalidLength {
                field: "roster_entries",
                value: i128::from(raw_count),
            })?;
            let mut values = ::std::vec::Vec::with_capacity(count);
            for _ in 0..count {
                values.push(WorldMapNodeState::parse(buf, offset)?);
            }
            values
        };
        let second_array_count = u32::from_le_bytes(self::read_array::<4>(buf, offset)?);
        let second_array = {
            let raw_count = second_array_count;
            #[allow(
                clippy::unnecessary_fallible_conversions,
                reason = "length fields can use signed or wide integer types"
            )]
            let count = usize::try_from(raw_count).map_err(|_| Error::InvalidLength {
                field: "second_array",
                value: i128::from(raw_count),
            })?;
            let mut values = ::std::vec::Vec::with_capacity(count);
            for _ in 0..count {
                values.push(u32::from_le_bytes(self::read_array::<4>(buf, offset)?));
            }
            values
        };
        let mission_completion = {
            let mut values = ::std::vec::Vec::with_capacity(20);
            for _ in 0..20 {
                values.push(u32::from_le_bytes(self::read_array::<4>(buf, offset)?));
            }
            <[_; 20]>::try_from(values).map_err(|values| Error::FixedSize {
                field: "mission_completion",
                expected: 20,
                actual: values.len(),
            })?
        };
        let current_mission_slot = u32::from_le_bytes(self::read_array::<4>(buf, offset)?);
        let tail_data = {
            let remaining = buf.len().saturating_sub(*offset);
            self::take(buf, offset, remaining)?.to_vec()
        };
        Ok(Self {
            size_prefix,
            magic,
            context_data,
            campaign_index,
            main_save_block,
            unit_count,
            units,
            selected_unit_ref,
            roster_count,
            roster_entries,
            second_array_count,
            second_array,
            mission_completion,
            current_mission_slot,
            tail_data,
        })
    }
}

impl File {
    #[allow(non_snake_case, reason = "schema field names are preserved")]
    #[allow(clippy::too_many_lines, reason = "schema methods follow field order")]
    pub fn to_bytes(&self) -> ::std::result::Result<::std::vec::Vec<u8>, Error> {
        let mut buf = ::std::vec::Vec::new();
        let value = &self.size_prefix;
        buf.extend_from_slice(&(*value).to_le_bytes());
        let value = &self.magic;
        buf.extend_from_slice(&(*value).to_le_bytes());
        let value = &self.context_data;
        buf.extend_from_slice(value);
        let value = &self.campaign_index;
        buf.extend_from_slice(&(*value).to_le_bytes());
        let value = &self.main_save_block;
        buf.extend_from_slice(value);
        let actual = self.units.len();
        let computed = u32::try_from(actual).map_err(|_| Error::LengthOverflow {
            field: "unit_count",
            value: actual.to_string(),
            target: "u32",
        })?;
        buf.extend_from_slice(&(computed).to_le_bytes());
        let value = &self.units;
        for item in value {
            buf.extend_from_slice(&item.to_bytes()?);
        }
        let value = &self.selected_unit_ref;
        buf.extend_from_slice(&(*value).to_le_bytes());
        let actual = self.roster_entries.len();
        let computed = u32::try_from(actual).map_err(|_| Error::LengthOverflow {
            field: "roster_count",
            value: actual.to_string(),
            target: "u32",
        })?;
        buf.extend_from_slice(&(computed).to_le_bytes());
        let value = &self.roster_entries;
        for item in value {
            buf.extend_from_slice(&item.to_bytes()?);
        }
        let actual = self.second_array.len();
        let computed = u32::try_from(actual).map_err(|_| Error::LengthOverflow {
            field: "second_array_count",
            value: actual.to_string(),
            target: "u32",
        })?;
        buf.extend_from_slice(&(computed).to_le_bytes());
        let value = &self.second_array;
        for item in value {
            buf.extend_from_slice(&(*item).to_le_bytes());
        }
        let value = &self.mission_completion;
        for item in value {
            buf.extend_from_slice(&(*item).to_le_bytes());
        }
        let value = &self.current_mission_slot;
        buf.extend_from_slice(&(*value).to_le_bytes());
        let value = &self.tail_data;
        buf.extend_from_slice(value);
        Ok(buf)
    }
}

